import{_ as a,o as d,c as e,ag as n}from"./chunks/framework.i8sMDeRW.js";const b=JSON.parse('{"title":"Token 经济学","description":"","frontmatter":{},"headers":[],"relativePath":"guide/09-monetization/token-economics.md","filePath":"guide/09-monetization/token-economics.md","lastUpdated":1778822660000}'),s={name:"guide/09-monetization/token-economics.md"};function r(i,t,l,p,o,h){return d(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="token-经济学" tabindex="-1">Token 经济学 <a class="header-anchor" href="#token-经济学" aria-label="Permalink to &quot;Token 经济学&quot;">​</a></h1><blockquote><p>AI 产品经理的成本控制指南：从推理成本拆解、模型路由、缓存策略，到 Agent 运行成本和账单保护。本文按 <strong>2026-05</strong> 的 AI 产品形态更新，尽量避免写死容易过期的模型名和价格。</p></blockquote><hr><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#1-推理成本结构拆解">推理成本结构拆解</a></li><li><a href="#2-产品设计层面的成本优化策略">产品设计层面的成本优化策略</a></li><li><a href="#3-限速熔断与账单保护">限速、熔断与账单保护</a></li><li><a href="#4-成本透明度设计">成本透明度设计</a></li><li><a href="#5-模型选型对定价的影响">模型选型对定价的影响</a></li><li><a href="#6-agent-成本管理">Agent 成本管理</a></li><li><a href="#7-附录成本测算模板">附录：成本测算模板</a></li></ol><hr><h2 id="_1-推理成本结构拆解" tabindex="-1">1. 推理成本结构拆解 <a class="header-anchor" href="#_1-推理成本结构拆解" aria-label="Permalink to &quot;1. 推理成本结构拆解&quot;">​</a></h2><h3 id="_1-1-一次-ai-调用的完整成本" tabindex="-1">1.1 一次 AI 调用的完整成本 <a class="header-anchor" href="#_1-1-一次-ai-调用的完整成本" aria-label="Permalink to &quot;1.1 一次 AI 调用的完整成本&quot;">​</a></h3><p>很多产品经理会把推理成本简化为“模型 API 价格 × 调用次数”。这在早期聊天产品里勉强可用，但在 2026 年的 AI 产品里已经不够。一次完整 AI 调用通常包含：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>单次总成本 = 输入 token 成本</span></span>
<span class="line"><span>          + 缓存输入 token 成本</span></span>
<span class="line"><span>          + 输出 token 成本</span></span>
<span class="line"><span>          + 系统提示词成本</span></span>
<span class="line"><span>          + 检索 / RAG 成本</span></span>
<span class="line"><span>          + 工具调用成本</span></span>
<span class="line"><span>          + Agent 多步执行成本</span></span>
<span class="line"><span>          + 重试与失败成本</span></span>
<span class="line"><span>          + 日志、审计与存储成本</span></span></code></pre></div><p>其中最容易被低估的是：<strong>上下文、工具调用、失败重试、Agent 步骤数</strong>。</p><table tabindex="0"><thead><tr><th>成本项</th><th>说明</th><th>常见优化手段</th></tr></thead><tbody><tr><td>输入 token</td><td>用户输入、系统提示词、历史对话、检索片段</td><td>压缩 prompt、滑动窗口、摘要记忆</td></tr><tr><td>缓存输入</td><td>重复系统提示词、重复文档上下文</td><td>Prompt caching、上下文复用</td></tr><tr><td>输出 token</td><td>模型生成内容</td><td>限制输出长度、结构化输出、流式截断</td></tr><tr><td>RAG 检索</td><td>向量检索、关键词检索、rerank</td><td>混合检索、Top-K 控制、缓存</td></tr><tr><td>工具调用</td><td>API、数据库、浏览器、代码执行</td><td>工具白名单、参数校验、超时限制</td></tr><tr><td>Agent 步骤</td><td>plan、act、observe、retry 的多轮循环</td><td>step budget、任务分级、人工审批</td></tr><tr><td>失败重试</td><td>超时、格式错误、工具错误后的重跑</td><td>自动修复上限、幂等设计、降级策略</td></tr><tr><td>审计存储</td><td>trace、日志、对话、工具结果</td><td>分级留存、采样、冷热存储</td></tr></tbody></table><h3 id="_1-2-输入成本-被低估的主要成本项" tabindex="-1">1.2 输入成本：被低估的主要成本项 <a class="header-anchor" href="#_1-2-输入成本-被低估的主要成本项" aria-label="Permalink to &quot;1.2 输入成本：被低估的主要成本项&quot;">​</a></h3><p>输入成本不只是用户写的那句话。真实产品中，输入通常包括：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入 = system prompt</span></span>
<span class="line"><span>     + developer / product instructions</span></span>
<span class="line"><span>     + 用户当前问题</span></span>
<span class="line"><span>     + 历史对话</span></span>
<span class="line"><span>     + RAG 检索结果</span></span>
<span class="line"><span>     + 工具定义 schema</span></span>
<span class="line"><span>     + 组织策略 / 权限上下文</span></span></code></pre></div><p><strong>典型客服 AI 会话示例</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>System Prompt: 800 tokens</span></span>
<span class="line"><span>工具 schema: 1,200 tokens</span></span>
<span class="line"><span>历史对话: 10 轮 × 300 tokens = 3,000 tokens</span></span>
<span class="line"><span>RAG 结果: 3 个片段 × 500 tokens = 1,500 tokens</span></span>
<span class="line"><span>当前输入: 100 tokens</span></span>
<span class="line"><span>总输入: 6,600 tokens</span></span></code></pre></div><p>用户以为只问了 100 tokens，但系统实际发送了 6,600 tokens。因此，PM 在设计 AI 功能时要重点关注“隐性上下文成本”。</p><h3 id="_1-3-输出成本-回答越长不一定价值越高" tabindex="-1">1.3 输出成本：回答越长不一定价值越高 <a class="header-anchor" href="#_1-3-输出成本-回答越长不一定价值越高" aria-label="Permalink to &quot;1.3 输出成本：回答越长不一定价值越高&quot;">​</a></h3><p>输出 token 通常比输入 token 更贵，而且长回答经常不等于高价值。</p><table tabindex="0"><thead><tr><th>陷阱</th><th>描述</th><th>解决方法</th></tr></thead><tbody><tr><td>回答过长</td><td>模型倾向生成完整解释</td><td>按场景设置输出上限</td></tr><tr><td>格式冗余</td><td>JSON、Markdown、表格会增加 token</td><td>只在必要时结构化</td></tr><tr><td>反复重写</td><td>用户不满意后整段重写</td><td>支持局部编辑 / diff 输出</td></tr><tr><td>隐式推理</td><td>复杂任务消耗更多 reasoning budget</td><td>按任务等级选择 reasoning 模式</td></tr><tr><td>安全重生成</td><td>输出被过滤后重跑</td><td>前置风险分类，减少无效生成</td></tr></tbody></table><p><strong>产品原则</strong>：</p><ul><li>客服场景：短、准、可执行；</li><li>教育场景：分步骤、可解释；</li><li>法务 / 金融 / 医疗：保守、引用来源、加免责声明；</li><li>代码场景：优先 diff、测试、注释，不要整文件重写；</li><li>Agent 场景：输出用户需要的结论，不展示所有中间噪音。</li></ul><h3 id="_1-4-工具调用成本" tabindex="-1">1.4 工具调用成本 <a class="header-anchor" href="#_1-4-工具调用成本" aria-label="Permalink to &quot;1.4 工具调用成本&quot;">​</a></h3><p>Agent 产品的成本经常不是模型本身，而是工具调用造成的连锁成本。</p><table tabindex="0"><thead><tr><th>调用类型</th><th>成本构成</th><th>风险</th></tr></thead><tbody><tr><td>数据库查询</td><td>查询资源 + 返回结果 token</td><td>返回过大导致上下文膨胀</td></tr><tr><td>搜索 / 浏览</td><td>搜索 API + 网页抓取 + 摘要</td><td>来源不稳定、延迟高</td></tr><tr><td>代码执行</td><td>沙箱资源 + 日志 + 安全扫描</td><td>超时、无限循环、供应链风险</td></tr><tr><td>外部 SaaS API</td><td>第三方 API 费用</td><td>失败重试放大成本</td></tr><tr><td>文件处理</td><td>OCR、解析、embedding、存储</td><td>大文件成本不可控</td></tr></tbody></table><blockquote><p><strong>Agent 成本警示</strong>：普通聊天可能只调用一次模型；Agent 任务可能包含 5-20 次模型调用、多个工具调用和若干失败重试。PM 必须为每类任务定义成本上限。</p></blockquote><h3 id="_1-5-缓存成本与缓存收益" tabindex="-1">1.5 缓存成本与缓存收益 <a class="header-anchor" href="#_1-5-缓存成本与缓存收益" aria-label="Permalink to &quot;1.5 缓存成本与缓存收益&quot;">​</a></h3><p>现代模型服务通常支持不同形式的缓存或批处理折扣。产品侧也可以自建缓存。</p><table tabindex="0"><thead><tr><th>缓存类型</th><th>适用场景</th><th>注意事项</th></tr></thead><tbody><tr><td>System Prompt 缓存</td><td>固定产品指令</td><td>prompt 频繁变更会降低命中率</td></tr><tr><td>文档上下文缓存</td><td>RAG / 文档问答</td><td>需要处理权限和文档更新</td></tr><tr><td>查询结果缓存</td><td>FAQ、政策问答、公开知识</td><td>需要过期策略</td></tr><tr><td>工具结果缓存</td><td>价格、库存、配置、权限</td><td>实时性要求高时谨慎</td></tr><tr><td>Embedding 缓存</td><td>重复文档处理</td><td>需要版本号和模型变更策略</td></tr></tbody></table><p><strong>缓存命中率比单价更重要</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>月成本 = 原始请求量 × 单次成本 × (1 - 缓存命中率 × 节省比例)</span></span></code></pre></div><p>例如缓存命中率 40%，命中后节省 70%，则整体成本可降低：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>40% × 70% = 28%</span></span></code></pre></div><hr><h2 id="_2-产品设计层面的成本优化策略" tabindex="-1">2. 产品设计层面的成本优化策略 <a class="header-anchor" href="#_2-产品设计层面的成本优化策略" aria-label="Permalink to &quot;2. 产品设计层面的成本优化策略&quot;">​</a></h2><h3 id="_2-1-模型分级-智能路由" tabindex="-1">2.1 模型分级：智能路由 <a class="header-anchor" href="#_2-1-模型分级-智能路由" aria-label="Permalink to &quot;2.1 模型分级：智能路由&quot;">​</a></h3><p>不要让所有请求都走最强模型。更合理的方式是把模型分为能力层级：</p><table tabindex="0"><thead><tr><th>层级</th><th>适用任务</th><th>成本特征</th></tr></thead><tbody><tr><td>本地 / 规则 / 模板</td><td>固定流程、FAQ、格式转换</td><td>接近零推理成本</td></tr><tr><td>Mini 模型</td><td>分类、摘要、简单问答、轻量路由</td><td>低成本、高吞吐</td></tr><tr><td>标准模型</td><td>普通知识工作、客服、文档问答</td><td>成本和质量平衡</td></tr><tr><td>高级推理模型</td><td>复杂规划、代码修复、深度分析</td><td>高成本，需限额</td></tr><tr><td>多模态 / 专用模型</td><td>图像、音频、视频、OCR</td><td>任务型成本明显</td></tr><tr><td>私有 / 本地部署模型</td><td>高隐私、低延迟、成本可控场景</td><td>运维成本高</td></tr></tbody></table><p><strong>路由策略示例</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户请求 → 意图识别 → 风险分类 → 成本预算判断 → 模型选择</span></span>
<span class="line"><span>                                      │</span></span>
<span class="line"><span>                                      ├─ 简单任务：规则 / mini 模型</span></span>
<span class="line"><span>                                      ├─ 标准任务：标准模型</span></span>
<span class="line"><span>                                      ├─ 高价值任务：高级推理模型</span></span>
<span class="line"><span>                                      └─ 高风险任务：强模型 + 审核 + 工具限制</span></span></code></pre></div><h3 id="_2-2-混合架构-ai-传统逻辑" tabindex="-1">2.2 混合架构：AI + 传统逻辑 <a class="header-anchor" href="#_2-2-混合架构-ai-传统逻辑" aria-label="Permalink to &quot;2.2 混合架构：AI + 传统逻辑&quot;">​</a></h3><p>不要让 AI 做传统逻辑能稳定完成的事情。</p><table tabindex="0"><thead><tr><th>场景</th><th>不推荐</th><th>推荐</th></tr></thead><tbody><tr><td>订单查询</td><td>让模型猜订单状态</td><td>API 查询 + 模型解释</td></tr><tr><td>FAQ</td><td>每次完整生成答案</td><td>检索 / 模板 + 少量改写</td></tr><tr><td>权限判断</td><td>让模型决定用户能否访问</td><td>权限系统硬判断</td></tr><tr><td>金额计算</td><td>让模型做数学</td><td>程序计算 + 模型说明</td></tr><tr><td>表单校验</td><td>让模型判断格式</td><td>正则 / schema 校验</td></tr><tr><td>高风险操作</td><td>模型直接执行</td><td>策略引擎 + 人工审批</td></tr></tbody></table><h3 id="_2-3-上下文窗口管理" tabindex="-1">2.3 上下文窗口管理 <a class="header-anchor" href="#_2-3-上下文窗口管理" aria-label="Permalink to &quot;2.3 上下文窗口管理&quot;">​</a></h3><p>上下文越长，成本越高，错误也可能更多。常见策略：</p><table tabindex="0"><thead><tr><th>策略</th><th>成本节省</th><th>质量影响</th><th>适用场景</th></tr></thead><tbody><tr><td>固定窗口</td><td>高</td><td>可能丢历史</td><td>短会话</td></tr><tr><td>滑动窗口</td><td>中高</td><td>较低</td><td>聊天、客服</td></tr><tr><td>摘要压缩</td><td>高</td><td>有信息损失</td><td>长会话</td></tr><tr><td>分层记忆</td><td>中高</td><td>好</td><td>Agent / 个人助手</td></tr><tr><td>检索式记忆</td><td>中</td><td>依赖检索质量</td><td>知识库、代码库</td></tr><tr><td>权限感知上下文</td><td>中</td><td>提高安全性</td><td>企业场景</td></tr></tbody></table><p>推荐默认策略：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>最近上下文精确保留 + 早期上下文摘要 + 长期记忆检索 + 权限过滤</span></span></code></pre></div><h3 id="_2-4-rag-成本优化" tabindex="-1">2.4 RAG 成本优化 <a class="header-anchor" href="#_2-4-rag-成本优化" aria-label="Permalink to &quot;2.4 RAG 成本优化&quot;">​</a></h3><p>RAG 不一定省钱。一个粗暴的 RAG 系统可能每次塞入大量无关片段，反而增加成本。</p><table tabindex="0"><thead><tr><th>优化点</th><th>做法</th></tr></thead><tbody><tr><td>Chunk 质量</td><td>按语义边界切分，保留标题、来源、时间</td></tr><tr><td>Top-K 控制</td><td>不固定塞满上下文，按置信度动态选择</td></tr><tr><td>Rerank</td><td>先粗检索，再重排序，减少无关片段</td></tr><tr><td>权限过滤</td><td>检索前过滤无权文档，避免泄露和浪费</td></tr><tr><td>引用压缩</td><td>只传关键句，不传整段原文</td></tr><tr><td>热点缓存</td><td>高频问题缓存答案和引用</td></tr></tbody></table><h3 id="_2-5-输出长度与格式控制" tabindex="-1">2.5 输出长度与格式控制 <a class="header-anchor" href="#_2-5-输出长度与格式控制" aria-label="Permalink to &quot;2.5 输出长度与格式控制&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>推荐输出策略</th></tr></thead><tbody><tr><td>客服</td><td>3-5 句 + 明确下一步</td></tr><tr><td>总结</td><td>TL;DR + 要点 + 可展开详情</td></tr><tr><td>代码</td><td>diff / patch 优先，避免整文件重写</td></tr><tr><td>数据分析</td><td>结论先行，表格按需展示</td></tr><tr><td>合规回答</td><td>保守措辞 + 来源 + 免责声明</td></tr><tr><td>Agent 任务</td><td>展示结果、关键动作和待确认事项</td></tr></tbody></table><hr><h2 id="_3-限速、熔断与账单保护" tabindex="-1">3. 限速、熔断与账单保护 <a class="header-anchor" href="#_3-限速、熔断与账单保护" aria-label="Permalink to &quot;3. 限速、熔断与账单保护&quot;">​</a></h2><h3 id="_3-1-限速维度" tabindex="-1">3.1 限速维度 <a class="header-anchor" href="#_3-1-限速维度" aria-label="Permalink to &quot;3.1 限速维度&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>说明</th></tr></thead><tbody><tr><td>用户级</td><td>每用户每分钟 / 每日 / 每月限制</td></tr><tr><td>组织级</td><td>团队或企业的总额度池</td></tr><tr><td>功能级</td><td>高成本功能单独限额</td></tr><tr><td>模型级</td><td>高级模型请求限制</td></tr><tr><td>工具级</td><td>搜索、代码执行、外部 API 单独限额</td></tr><tr><td>Agent 级</td><td>每次 run 的最大 step、最大时长、最大成本</td></tr></tbody></table><h3 id="_3-2-熔断策略" tabindex="-1">3.2 熔断策略 <a class="header-anchor" href="#_3-2-熔断策略" aria-label="Permalink to &quot;3.2 熔断策略&quot;">​</a></h3><table tabindex="0"><thead><tr><th>触发条件</th><th>动作</th></tr></thead><tbody><tr><td>单用户请求异常暴增</td><td>临时限流 + 验证码 / 风险检查</td></tr><tr><td>组织预算接近上限</td><td>告警 + 降级到低成本模型</td></tr><tr><td>模型供应商异常</td><td>切换备选模型</td></tr><tr><td>工具错误率升高</td><td>暂停该工具，改为人工或只读模式</td></tr><tr><td>Agent 重试过多</td><td>停止执行，要求人工确认</td></tr><tr><td>月成本超预算</td><td>全局降级、关闭非关键高成本功能</td></tr></tbody></table><h3 id="_3-3-账单保护设计" tabindex="-1">3.3 账单保护设计 <a class="header-anchor" href="#_3-3-账单保护设计" aria-label="Permalink to &quot;3.3 账单保护设计&quot;">​</a></h3><p>AI 产品必须避免“账单惊吓”。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>预算设置 → 使用提醒 → 接近上限 → 自动降级 / 暂停 → 手动确认超额</span></span></code></pre></div><p>建议提供：</p><ul><li>月度预算上限；</li><li>50% / 80% / 100% 使用量提醒；</li><li>超额后自动暂停或降级；</li><li>按用户、项目、模型、工具拆账；</li><li>企业管理员可导出成本明细；</li><li>Agent run 级别的成本预估和执行上限。</li></ul><hr><h2 id="_4-成本透明度设计" tabindex="-1">4. 成本透明度设计 <a class="header-anchor" href="#_4-成本透明度设计" aria-label="Permalink to &quot;4. 成本透明度设计&quot;">​</a></h2><h3 id="_4-1-面向不同用户展示不同粒度" tabindex="-1">4.1 面向不同用户展示不同粒度 <a class="header-anchor" href="#_4-1-面向不同用户展示不同粒度" aria-label="Permalink to &quot;4.1 面向不同用户展示不同粒度&quot;">​</a></h3><table tabindex="0"><thead><tr><th>用户类型</th><th>推荐展示</th></tr></thead><tbody><tr><td>C 端用户</td><td>消息额度、图片额度、高级功能额度</td></tr><tr><td>专业用户</td><td>credits、premium requests、上下文长度</td></tr><tr><td>开发者</td><td>token、模型单价、API 调用明细</td></tr><tr><td>企业管理员</td><td>成本中心、项目账单、用户排行、异常告警</td></tr><tr><td>财务 / 采购</td><td>月度汇总、合同用量、超额费用、ROI 报告</td></tr></tbody></table><h3 id="_4-2-不建议直接暴露-token-给所有人" tabindex="-1">4.2 不建议直接暴露 token 给所有人 <a class="header-anchor" href="#_4-2-不建议直接暴露-token-给所有人" aria-label="Permalink to &quot;4.2 不建议直接暴露 token 给所有人&quot;">​</a></h3><p>Token 对开发者有意义，但对多数用户没有意义。更好的抽象是：</p><table tabindex="0"><thead><tr><th>产品类型</th><th>用户可理解单位</th></tr></thead><tbody><tr><td>聊天助手</td><td>消息、高级模型额度</td></tr><tr><td>图像生成</td><td>张数、GPU 时间、fast hours</td></tr><tr><td>编程助手</td><td>premium requests、agent runs</td></tr><tr><td>知识库</td><td>文档数、检索次数、成员数</td></tr><tr><td>Agent 平台</td><td>runs、steps、credits、工具调用</td></tr><tr><td>API 平台</td><td>token、请求数、批处理任务</td></tr></tbody></table><hr><h2 id="_5-模型选型对定价的影响" tabindex="-1">5. 模型选型对定价的影响 <a class="header-anchor" href="#_5-模型选型对定价的影响" aria-label="Permalink to &quot;5. 模型选型对定价的影响&quot;">​</a></h2><h3 id="_5-1-不要只选-最强模型" tabindex="-1">5.1 不要只选“最强模型” <a class="header-anchor" href="#_5-1-不要只选-最强模型" aria-label="Permalink to &quot;5.1 不要只选“最强模型”&quot;">​</a></h3><p>模型选型要同时看：</p><table tabindex="0"><thead><tr><th>维度</th><th>问题</th></tr></thead><tbody><tr><td>质量</td><td>是否满足目标任务？</td></tr><tr><td>成本</td><td>平均每次任务成本多少？</td></tr><tr><td>延迟</td><td>P50 / P95 / P99 是否可接受？</td></tr><tr><td>上下文</td><td>是否需要长文档 / 代码库 / 多文件？</td></tr><tr><td>工具调用</td><td>工具选择和参数生成是否稳定？</td></tr><tr><td>多模态</td><td>是否需要图像、语音、视频？</td></tr><tr><td>合规</td><td>数据是否可出境？是否用于训练？</td></tr><tr><td>可替换性</td><td>是否能接入备选模型？</td></tr></tbody></table><h3 id="_5-2-模型组合策略" tabindex="-1">5.2 模型组合策略 <a class="header-anchor" href="#_5-2-模型组合策略" aria-label="Permalink to &quot;5.2 模型组合策略&quot;">​</a></h3><table tabindex="0"><thead><tr><th>产品阶段</th><th>推荐策略</th></tr></thead><tbody><tr><td>Prototype</td><td>用强模型验证天花板</td></tr><tr><td>MVP</td><td>强模型 + mini 模型路由，验证单位经济学</td></tr><tr><td>增长期</td><td>多供应商、多模型路由，建立成本监控</td></tr><tr><td>企业化</td><td>加入私有部署、区域模型、审计和数据控制</td></tr><tr><td>成熟期</td><td>建立模型抽象层，按任务动态选择最优模型</td></tr></tbody></table><h3 id="_5-3-定价联动" tabindex="-1">5.3 定价联动 <a class="header-anchor" href="#_5-3-定价联动" aria-label="Permalink to &quot;5.3 定价联动&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模型成本变化</th><th>产品策略</th></tr></thead><tbody><tr><td>强模型降价</td><td>提升付费层额度，或提高毛利</td></tr><tr><td>新强模型变贵</td><td>放入 Pro / Enterprise 层，不进免费层</td></tr><tr><td>mini 模型质量提升</td><td>扩大免费层或降低入门价</td></tr><tr><td>多模态成本下降</td><td>把图片 / 音频功能从附加项变成套餐内能力</td></tr><tr><td>Agent 成本上升</td><td>改为 runs / credits / step budget 定价</td></tr></tbody></table><hr><h2 id="_6-agent-成本管理" tabindex="-1">6. Agent 成本管理 <a class="header-anchor" href="#_6-agent-成本管理" aria-label="Permalink to &quot;6. Agent 成本管理&quot;">​</a></h2><h3 id="_6-1-agent-成本公式" tabindex="-1">6.1 Agent 成本公式 <a class="header-anchor" href="#_6-1-agent-成本公式" aria-label="Permalink to &quot;6.1 Agent 成本公式&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Agent run 成本 = 规划调用成本</span></span>
<span class="line"><span>              + Σ(每一步模型调用成本)</span></span>
<span class="line"><span>              + Σ(工具调用成本)</span></span>
<span class="line"><span>              + Σ(观察结果写回上下文成本)</span></span>
<span class="line"><span>              + 验证 / 评估成本</span></span>
<span class="line"><span>              + 失败重试成本</span></span>
<span class="line"><span>              + 审计 trace 存储成本</span></span></code></pre></div><h3 id="_6-2-agent-成本控制旋钮" tabindex="-1">6.2 Agent 成本控制旋钮 <a class="header-anchor" href="#_6-2-agent-成本控制旋钮" aria-label="Permalink to &quot;6.2 Agent 成本控制旋钮&quot;">​</a></h3><table tabindex="0"><thead><tr><th>旋钮</th><th>说明</th></tr></thead><tbody><tr><td>最大 step 数</td><td>防止无限循环</td></tr><tr><td>最大运行时间</td><td>防止长时间占用资源</td></tr><tr><td>最大工具调用次数</td><td>防止 API 成本失控</td></tr><tr><td>最大上下文长度</td><td>防止每步输入持续膨胀</td></tr><tr><td>最大重试次数</td><td>防止失败任务反复烧钱</td></tr><tr><td>工具权限等级</td><td>高风险工具需审批</td></tr><tr><td>阶段性确认</td><td>到达成本阈值后询问用户</td></tr><tr><td>低价值任务拒绝</td><td>任务收益小于成本时提示用户改写</td></tr></tbody></table><h3 id="_6-3-agent-分层定价" tabindex="-1">6.3 Agent 分层定价 <a class="header-anchor" href="#_6-3-agent-分层定价" aria-label="Permalink to &quot;6.3 Agent 分层定价&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层级</th><th>适合用户</th><th>成本控制方式</th></tr></thead><tbody><tr><td>Free</td><td>体验 Agent 能力</td><td>少量 run、低 step、低优先级</td></tr><tr><td>Plus / Pro</td><td>个人重度使用</td><td>每月 included runs + 高级模型额度</td></tr><tr><td>Team</td><td>团队协作</td><td>组织额度池 + 成员管理 + 用量分析</td></tr><tr><td>Business</td><td>高价值工作流</td><td>更高额度、SSO、审计、数据保护</td></tr><tr><td>Enterprise</td><td>关键业务流程</td><td>自定义额度、专属容量、私有部署、SLA</td></tr></tbody></table><hr><h2 id="_7-附录-成本测算模板" tabindex="-1">7. 附录：成本测算模板 <a class="header-anchor" href="#_7-附录-成本测算模板" aria-label="Permalink to &quot;7. 附录：成本测算模板&quot;">​</a></h2><h3 id="_7-1-单次任务成本" tabindex="-1">7.1 单次任务成本 <a class="header-anchor" href="#_7-1-单次任务成本" aria-label="Permalink to &quot;7.1 单次任务成本&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入 token: ______</span></span>
<span class="line"><span>缓存输入 token: ______</span></span>
<span class="line"><span>输出 token: ______</span></span>
<span class="line"><span>模型单价: 输入 ______ / 输出 ______</span></span>
<span class="line"><span>RAG 检索成本: ______</span></span>
<span class="line"><span>工具调用次数: ______</span></span>
<span class="line"><span>工具调用单价: ______</span></span>
<span class="line"><span>平均重试次数: ______</span></span>
<span class="line"><span>审计 / 存储成本: ______</span></span>
<span class="line"><span></span></span>
<span class="line"><span>单次任务成本 = ______</span></span></code></pre></div><h3 id="_7-2-月度成本测算" tabindex="-1">7.2 月度成本测算 <a class="header-anchor" href="#_7-2-月度成本测算" aria-label="Permalink to &quot;7.2 月度成本测算&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>月活用户数: ______</span></span>
<span class="line"><span>人均月任务数: ______</span></span>
<span class="line"><span>任务总数 = 月活用户数 × 人均月任务数</span></span>
<span class="line"><span>平均单次任务成本: ______</span></span>
<span class="line"><span>缓存节省比例: ______</span></span>
<span class="line"><span>失败重试放大系数: ______</span></span>
<span class="line"><span></span></span>
<span class="line"><span>月推理成本 = 任务总数 × 平均单次成本 × (1 - 缓存节省比例) × 失败重试放大系数</span></span></code></pre></div><h3 id="_7-3-毛利率测算" tabindex="-1">7.3 毛利率测算 <a class="header-anchor" href="#_7-3-毛利率测算" aria-label="Permalink to &quot;7.3 毛利率测算&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>月收入 = 付费用户数 × ARPU</span></span>
<span class="line"><span>月 AI 成本 = 推理 + 工具 + 检索 + 存储 + 审计</span></span>
<span class="line"><span>其他云成本 = ______</span></span>
<span class="line"><span>支持与运营成本 = ______</span></span>
<span class="line"><span></span></span>
<span class="line"><span>毛利率 = (月收入 - 月 AI 成本 - 其他云成本 - 支持与运营成本) / 月收入</span></span></code></pre></div><h3 id="_7-4-上线前成本-checklist" tabindex="-1">7.4 上线前成本 Checklist <a class="header-anchor" href="#_7-4-上线前成本-checklist" aria-label="Permalink to &quot;7.4 上线前成本 Checklist&quot;">​</a></h3><ul><li>[ ] 已测算免费用户月均成本；</li><li>[ ] 已测算付费用户 P50 / P95 / P99 成本；</li><li>[ ] 已设置用户级、组织级、Agent run 级预算；</li><li>[ ] 已配置高级模型限额；</li><li>[ ] 已配置工具调用上限；</li><li>[ ] 已配置异常用量告警；</li><li>[ ] 已有模型降级和供应商切换策略；</li><li>[ ] 已定义超额计费或降级规则；</li><li>[ ] 已准备企业用量报表；</li><li>[ ] 已建立季度价格和模型成本复核机制。</li></ul><hr><h2 id="参考来源" tabindex="-1">参考来源 <a class="header-anchor" href="#参考来源" aria-label="Permalink to &quot;参考来源&quot;">​</a></h2><ul><li>OpenAI API Pricing: <a href="https://openai.com/api/pricing/" target="_blank" rel="noreferrer">https://openai.com/api/pricing/</a></li><li>Anthropic Claude Pricing: <a href="https://docs.anthropic.com/en/docs/about-claude/pricing" target="_blank" rel="noreferrer">https://docs.anthropic.com/en/docs/about-claude/pricing</a></li><li>GitHub Copilot plans and premium requests: <a href="https://docs.github.com/en/copilot/get-started/plans" target="_blank" rel="noreferrer">https://docs.github.com/en/copilot/get-started/plans</a></li><li>Cursor Pricing: <a href="https://cursor.com/pricing" target="_blank" rel="noreferrer">https://cursor.com/pricing</a></li><li>Notion Custom Agent pricing: <a href="https://www.notion.com/help/custom-agent-pricing" target="_blank" rel="noreferrer">https://www.notion.com/help/custom-agent-pricing</a></li></ul><hr><blockquote><p><strong>结语</strong>：Token 经济学的目标不是让用户少用 AI，而是让每一次 AI 调用都用在真正产生价值的地方。优秀的 AI PM 既要会算成本，也要会通过产品设计把成本变成可感知、可控制、可持续的价值。</p></blockquote>`,104)])])}const _=a(s,[["render",r]]);export{b as __pageData,_ as default};
